Author:     John Bieling <john@thunderbird.net>
AuthorDate: Wed Feb 26 16:41:54 2025 +0100
Commit:     John Bieling <john@thunderbird.net>
CommitDate: Wed Feb 26 16:41:54 2025 +0100

    Bug 1945157 - Attempt to fix intermittent fail in browser_mailTelemetry.js. r=kaie

    While trying to understand the intermittent fail, it was observed that
    the test is not testing what it should and that the implementation
    to report telemetry data is broken.

    This patch aims to fix the test and the implementation without changing
    the intention of the original implementation.

    1. What is wrong with the implementation?

    Logs (see [1]) from a test with more debug output shows, that we record
    two records for the first encrypted S/MIME message, but none for the
    second. The OpenPGP message is recorded as `is_encrypted: false`.

    This is caused by the load process of encrypted messages, which
    get reloaded multiple times when they are displayed. This clears the
    read flag and the so far collected telemetry data. Any incoming data
    after a reload which cleared the read flag is ignored.

    2. Why is the test still passing, if there is no telemetry for the
    second message and the OpenPGP message is marked as "not encrypted"?

    The test is using a faulty filter to reduce the seen events to encrypted
    messages only. The statement assumes that the glean entry for
    `is_encrypted` is a boolean, but is in fact a string (either `"true"` or
    `"false"`). The filter condition therefore returns `true` for
    `is_encrypted` being set to `"false"`.

    3. What does this patch do?

    The telemetry data is no longer cleared on reload, but only if a
    different message is loaded (idea from Geoff, see [2]). When data is
    collected, we initiate a timer to process the collected data, but the
    timer gets reset each time a new telemetry information comes in. This
    will give us a single telemetry set per message with the required
    information (security, is_encrypted and is_signed).

    The intermittent is fixed by introducing a new `CustomEvent`, which
    tells the test and other consumers, when telemetry data has been
    processed.

    [1] : https://phabricator.services.mozilla.com/D239902#8284314
    [2] : https://phabricator.services.mozilla.com/D197795#7213166

    Differential Revision: https://phabricator.services.mozilla.com/D239902

diff --git a/mail/base/content/msgHdrView.js b/mail/base/content/msgHdrView.js
index 32e39fdec3f..179765fc6c7 100644
--- a/mail/base/content/msgHdrView.js
+++ b/mail/base/content/msgHdrView.js
@@ -1449,7 +1449,6 @@ function UpdateExpandedMessageHeaders() {
 }

 function ClearCurrentHeaders() {
-  gSecureMsgProbe = {};
   // eslint-disable-next-line no-global-assign
   currentHeaderData = {};
   // eslint-disable-next-line no-global-assign
@@ -4408,31 +4407,88 @@ function IgnoreMDNResponse() {
   gMessageNotificationBar.mdnGenerator.userDeclined();
 }

-// An object to help collecting reading statistics of secure emails.
-var gSecureMsgProbe = {};
+// A Map() to help collecting statistics of emails.
+var gMsgProbe = new Map();

 /**
- * Update gSecureMsgProbe and report to telemetry if necessary.
+ * Process and clear the collected telemetry data.
+ */
+function flushPendingTelemetryData() {
+  // Clear any pending action.
+  window.clearTimeout(gMsgProbe.get("timeoutId"));
+
+  const security = gMsgProbe.get("security");
+
+  // Only process telemetry for encrypted and/or signed messages.
+  if (security) {
+    let skipped = true;
+
+    // Skip telemetry data for messages which are not new.
+    if (gMsgProbe.has("isNewRead")) {
+      const is_signed = gMsgProbe.has("is_signed");
+      const is_encrypted = gMsgProbe.has("is_encrypted");
+      Glean.mail.mailsReadSecure.record({ security, is_signed, is_encrypted });
+      skipped = false;
+    }
+
+    // Let tests and other consumers know when the data has been processed or
+    // skipped.
+    window.dispatchEvent(
+      new CustomEvent("MsgSecurityTelemetryProcessed", {
+        bubbles: true,
+        detail: {
+          skipped,
+        },
+      })
+    );
+  }
+
+  // Reset collected data.
+  gMsgProbe.clear();
+}
+
+/**
+ * Update gMsgProbe and schedule submission of collected telemetry if necessary.
  */
 function reportMsgRead({ isNewRead = false, key = null }) {
+  // Usually telemetry data is processed after a short delay to ensure all data
+  // has been captured and the full telemetry information is available (security,
+  // is_signed and is_encrypted). Forcfully process any pending telemetry data,
+  // if a different message is loaded.
+  let pendingMsgURI = gMsgProbe.get("messageURI");
+  if (pendingMsgURI && pendingMsgURI != gMessageURI) {
+    flushPendingTelemetryData();
+    pendingMsgURI = undefined;
+  }
+
+  // Update probe data.
+  if (!pendingMsgURI) {
+    gMsgProbe.set("messageURI", gMessageURI);
+  }
   if (isNewRead) {
-    gSecureMsgProbe.isNewRead = true;
+    gMsgProbe.set("isNewRead", true);
   }
   if (key) {
-    gSecureMsgProbe.key = key;
-  }
-  if (gSecureMsgProbe.key && gSecureMsgProbe.isNewRead) {
     // The key is one of:
     // - 'signed-smime'
     // - 'signed-openpgp'
     // - 'encrypted-smime'
     // - 'encrypted-openpgp'
-    const is_signed = gSecureMsgProbe.key.startsWith("signed-");
-    const is_encrypted = gSecureMsgProbe.key.startsWith("encrypted-");
-    const security = gSecureMsgProbe.key.endsWith("-openpgp")
-      ? "OpenPGP"
-      : "S/MIME";
-    Glean.mail.mailsReadSecure.record({ security, is_signed, is_encrypted });
+    if (key.startsWith("signed-")) {
+      gMsgProbe.set("is_signed", true);
+    }
+    if (key.startsWith("encrypted-")) {
+      gMsgProbe.set("is_encrypted", true);
+    }
+    gMsgProbe.set("security", key.endsWith("-openpgp") ? "OpenPGP" : "S/MIME");
+
+    // This seems to be an encrypted and/or signed message. Schedule to process
+    // the collected telemetry data.
+    window.clearTimeout(gMsgProbe.get("timeoutId"));
+    gMsgProbe.set(
+      "timeoutId",
+      window.setTimeout(flushPendingTelemetryData, 500)
+    );
   }
 }

